UPDATE t_question q SET chapter_id=e.l3_id FROM l3map e WHERE q.id=e.qid;

DELETE FROM t_question_kp WHERE kp_id BETWEEN 32729 AND 32734;
UPDATE t_knowledge_point SET deleted=true WHERE id BETWEEN 32729 AND 32734;

DO $$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM t_question q JOIN l3map e ON e.qid=q.id JOIN t_chapter c ON c.id=q.chapter_id
   WHERE c.level=3 AND q.chapter_id=e.l3_id;
  IF n <> 131 THEN RAISE EXCEPTION '下移应为131，实际%', n; END IF;
  SELECT count(*) INTO n FROM t_question_kp WHERE kp_id BETWEEN 32729 AND 32734;
  IF n <> 0 THEN RAISE EXCEPTION '伞形链接残留%', n; END IF;
  SELECT count(*) INTO n FROM t_knowledge_point WHERE id BETWEEN 32729 AND 32734 AND NOT deleted;
  IF n <> 0 THEN RAISE EXCEPTION '伞形KP未删%', n; END IF;
  SELECT count(*) INTO n FROM t_question WHERE NOT deleted; IF n<>44323 THEN RAISE EXCEPTION '活跃数'; END IF;
END $$;
